static class Program {
 [DllImport("user32.dll")]static extern bool PrintWindow(nint window,nint target,uint flags);
 static void Capture(Form form,string name){form.Update();using var image=new Bitmap(form.Width,form.Height);using(var graphics=Graphics.FromImage(image)){var dc=graphics.GetHdc();try{Check(PrintWindow(form.Handle,dc,2),"Owned native capture failed");}finally{graphics.ReleaseHdc(dc);}}Check(Enumerable.Range(0,32).Select(i=>image.GetPixel(i*(image.Width-1)/31,i*(image.Height-1)/31).ToArgb()).Distinct().Count()>1,"Owned native capture is uniform; do not treat an all-black frame as visual proof");image.Save(Path.Combine(output,name+".png"));}
 static void CheckHeader(RecordDocument view){view.PerformLayout();var grid=Tree(view).OfType<DataGridView>().Single();var bar=Tree(view).OfType<ToolStrip>().Single();var header=grid.RectangleToScreen(grid.GetCellDisplayRectangle(0,-1,true));var toolbar=bar.RectangleToScreen(bar.ClientRectangle);Check(grid.ColumnHeadersVisible&&header.Height>0&&header.Top>=toolbar.Bottom,"Column captions overlap toolbar");var notice=view.Controls.OfType<Label>().Single();Check(grid.RectangleToScreen(grid.ClientRectangle).Bottom<=notice.RectangleToScreen(notice.ClientRectangle).Top,"Grid overlaps status notice");}
 static IEnumerable<ToolStripItem> Commands(ToolStripItemCollection items){foreach(ToolStripItem item in items){yield return item;if(item is ToolStripDropDownItem menu)foreach(var child in Commands(menu.DropDownItems))yield return child;}}
 static int pass,fail;static readonly List<object> checks=[];static string output="";
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static IEnumerable<Control> Tree(Control c){yield return c;foreach(Control ch in c.Controls)foreach(var x in Tree(ch))yield return x;}
 static async Task Test(string n,Func<Task> f){try{await f();pass++;checks.Add(new{name=n,ok=true});Console.WriteLine("PASS "+n);}catch(Exception e){fail++;checks.Add(new{name=n,ok=false,error=e.ToString()});Console.WriteLine("FAIL "+n+" "+e);}}
 static async Task Throws(Func<Task> f,string code){try{await f();}catch(WorkspaceException e){Check(e.Code==code,e.Code);return;}throw new Exception("Expected "+code);}
 [STAThread]static int Main(string[] args){ApplicationConfiguration.Initialize();output=Path.GetFullPath(args.FirstOrDefault()??("artifacts/local-modules66-"+Guid.NewGuid().ToString("N")));if(Directory.Exists(output))throw new Exception("fresh output required");Directory.CreateDirectory(output);var exactPackage=args.ElementAtOrDefault(1);if(exactPackage is not null){foreach(var (type,relative)in new (Type,string)[]{(typeof(WorkRecord),"Jindan.Contracts.dll"),(typeof(DomainRules),"Jindan.Core.dll"),(typeof(RecordDocument),"Jindan.Desktop.Contracts.dll"),(typeof(LocalWorkspace),"Jindan.Infrastructure.dll"),(typeof(FileDocument),"modules/files/Jindan.Modules.Files.dll"),(typeof(BoardDocument),"modules/board/Jindan.Modules.Board.dll")})Check(SHA256.HashData(File.ReadAllBytes(type.Assembly.Location)).SequenceEqual(SHA256.HashData(File.ReadAllBytes(Path.Combine(exactPackage,relative)))),"Loaded assembly differs from exact review package: "+relative);pass++;checks.Add(new{name="six loaded library and Files/Board DLLs match exact review package bytes",ok=true,package=Path.GetFullPath(exactPackage)});}using var store=new LocalWorkspace(Path.Combine(output,"data"));var actor=store.BootstrapAsync("Local module synthetic","local-module-66-test",true).GetAwaiter().GetResult();var services=new Services(actor,store);var filesModule=new Jindan.Modules.Files.Module();var boardModule=new Jindan.Modules.Board.Module();filesModule.Initialize(services);boardModule.Initialize(services);store.RegisterSchema(new("projects","Projects",[new("title","Title",Required:true)],false));var p=store.SaveAsync(actor,new(null,"projects",null,0,new(){{"title","합성 자료 프로젝트"}})).GetAwaiter().GetResult();var q=store.SaveAsync(actor,new(null,"projects",null,0,new(){{"title","다른 합성 프로젝트"}})).GetAwaiter().GetResult();using var form=new Form(){Text="격리 로컬 자료·게시판 UI 검증",Width=1100,Height=760};using var files=new FileDocument(services,filesModule.Schema,new("local-files-ui","files",p.Id,actor.Id));using var board=new BoardDocument(services,boardModule.Schema,new("local-board-ui","board",p.Id,actor.Id));var tabs=new TabControl(){Dock=DockStyle.Fill};var ftab=new TabPage("로컬 자료");ftab.Controls.Add(files);files.NavigationPanel.Dock=DockStyle.Left;files.NavigationPanel.Width=250;ftab.Controls.Add(files.NavigationPanel);var btab=new TabPage("게시글·첨부");btab.Controls.Add(board);tabs.TabPages.AddRange([ftab,btab]);form.Controls.Add(tabs);form.Shown+=async(_,_)=>{try{await files.Ready;await Task.Delay(250);form.Invalidate(true);form.Update();
 await Test("file column captions, tile surface and navigation remain outside toolbars",()=>{CheckHeader(files);var folderTree=Tree(files.NavigationPanel).OfType<TreeView>().Single();var top=files.NavigationPanel.Controls.Cast<Control>().Single(c=>c.Dock==DockStyle.Top);files.NavigationPanel.PerformLayout();Check(folderTree.RectangleToScreen(folderTree.ClientRectangle).Top>=top.RectangleToScreen(top.ClientRectangle).Bottom,"Folder tree overlaps search/navigation header");files.SetTileView(true);files.PerformLayout();var tile=Tree(files).OfType<ListView>().Single();var bar=Tree(files).OfType<ToolStrip>().Single();Check(tile.RectangleToScreen(tile.ClientRectangle).Top>=bar.RectangleToScreen(bar.ClientRectangle).Bottom,"Tiles overlap toolbar");Capture(form,"files-tiles-native-window");files.SetTileView(false);CheckHeader(files);Capture(form,"files-list-native-window");return Task.CompletedTask;});
 var original=Path.Combine(output,"original.txt");await File.WriteAllTextAsync(original,"SYNTHETIC source 66");var originalSha=SHA256.HashData(await File.ReadAllBytesAsync(original));WorkRecord? folder=null,child=null,file=null,post=null;
 await Test("actual native file import preserves source and duplicate identity",async()=>{file=await files.ImportPathAsync(original);var same=await files.ImportPathAsync(original);Check(file.Id==same.Id,"Duplicate content metadata was recreated");await files.RefreshAsync();Check(Tree(files).OfType<DataGridView>().Single().Rows.Count==1,"Native imported file not visible");Check(SHA256.HashData(await File.ReadAllBytesAsync(original)).SequenceEqual(originalSha),"Original modified");});
 await Test("native local folder creation and move preserve immutable asset",async()=>{folder=await files.CreateFolderAsync("조사 자료");child=await files.CreateFolderAsync("계측 자료",folder.Id);await files.MoveToFolderAsync(file!.Id,child.Id);await files.RefreshAsync();var moved=(await store.ListAsync(actor,new RecordQuery("files",p.Id))).Single();Check(moved.Fields["folderId"]==child.Id&&moved.Fields["assetId"]==file.Fields["assetId"],"Move changed asset identity");Check(Tree(files.NavigationPanel).OfType<TreeView>().Single().Nodes[0].Nodes.Count==1,"Native folder hierarchy missing");});
 await Test("folder cycle/cross-project/duplicate/path and nonempty deletion guards",async()=>{await Throws(()=>files.CreateFolderAsync("../bad"),"FOLDER_NAME");await Throws(()=>files.CreateFolderAsync("조사 자료"),"DUPLICATE_FOLDER");var other=await store.SaveAsync(actor,new(null,"file-folders",q.Id,0,new(){{"title","다른 폴더"}}));await Throws(()=>files.MoveToFolderAsync(file!.Id,other.Id),"PROJECT_SCOPE");await Throws(()=>store.SaveAsync(actor,new(folder!.Id,"file-folders",p.Id,folder.Revision,new(){{"title","조사 자료"},{"parentId",child!.Id}})),"FOLDER_CYCLE");await Throws(()=>store.DeleteAsync(actor,"file-folders",child!.Id,child.Revision,true),"FOLDER_NOT_EMPTY");});
 await Test("selected ZIP contains exact original bytes and manifest; cancel leaves no output",async()=>{var zipPath=await files.ExportSelectionZipAsync([file!.Id]);using var zip=ZipFile.OpenRead(zipPath);var entry=zip.Entries.Single(e=>e.FullName.StartsWith("files/"));using var stream=entry.Open();Check(SHA256.HashData(stream).SequenceEqual(originalSha),"ZIP changed original bytes");Check(zip.GetEntry("manifest.json") is not null,"Manifest missing");try{await files.ExportSelectionZipAsync([file.Id],new CancellationToken(true));throw new Exception("Cancellation ignored");}catch(OperationCanceledException){}Check(Directory.GetFiles(Path.Combine(store.DataRoot,"exports"),"*.zip").Length==1,"Cancelled export left partial file");});
 await Test("native folder back/forward and tile view follow current project without losing original assets",async()=>{await files.NavigateFolderAsync(child!.Id);var tree=Tree(files.NavigationPanel).OfType<TreeView>().Single();Check((string)tree.SelectedNode!.Tag! ==child.Id,"Folder navigation not visible");await files.NavigateFolderAsync("");await files.NavigateHistoryAsync(false);Check((string)tree.SelectedNode!.Tag! ==child.Id,"Back history missing");await files.NavigateHistoryAsync(true);Check((string)tree.SelectedNode!.Tag! =="","Forward history missing");await files.NavigateFolderAsync(child.Id);files.SetTileView(true);var tile=Tree(files).OfType<ListView>().Single();Check(tile.Visible&&tile.Items.Count==1&&((WorkRecord)tile.Items[0].Tag!).Id==file!.Id,"Native tile view does not match bounded row list");files.SetTileView(false);Check(Tree(files).OfType<DataGridView>().Single().Visible,"Detailed list did not return");});
 await Test("dropped file imports and rename/move commands preserve original bytes and reject invalid/cancelled input",async()=>{var extra=Path.Combine(output,"dropped.txt");await File.WriteAllTextAsync(extra,"SYNTHETIC dropped file");await files.ImportDroppedPathsAsync([extra]);var row=(await store.ListAsync(actor,new RecordQuery("files",p.Id))).Single(r=>r.Fields["title"]=="dropped.txt");await files.RenameFileAsync(row.Id,"renamed-copy.txt");await files.MoveSelectionToFolderAsync([row.Id],"");var saved=(await store.ListAsync(actor,new RecordQuery("files",p.Id))).Single(r=>r.Id==row.Id);Check(saved.Fields["folderId"]==""&&saved.Fields["assetId"]==row.Fields["assetId"]&&saved.Fields["title"]=="renamed-copy.txt","Native move or rename changed immutable asset link");try{await files.ImportDroppedPathsAsync([output]);throw new Exception("Directory accepted as file drop");}catch(InvalidOperationException){}try{await files.ImportDroppedPathsAsync([extra],new CancellationToken(true));throw new Exception("Cancelled drop accepted");}catch(OperationCanceledException){}await store.DeleteAsync(actor,"files",saved.Id,saved.Revision,true);Check(SHA256.HashData(await File.ReadAllBytesAsync(original)).SequenceEqual(originalSha),"Navigation/drop/rename changed original");await files.NavigateFolderAsync("");});
 tabs.SelectedTab=btab;await board.Ready;
 await Test("board column captions and thread remain outside toolbar and notice",()=>{CheckHeader(board);var thread=Tree(board).OfType<RichTextBox>().Single();var notice=board.Controls.OfType<Label>().Single();Check(thread.RectangleToScreen(thread.ClientRectangle).Bottom<=notice.RectangleToScreen(notice.ClientRectangle).Top,"Thread overlaps notice");Capture(form,"board-native-window");return Task.CompletedTask;});
 await Test("native post local attachments, service ACL and explicit reply action",async()=>{board.NewRecord();board.SetField("title","합성 첨부 게시글");board.SetField("content","과거 값이나 회사 자료가 없는 합성 본문");await board.AttachLocalFilesAsync([original]);await board.SaveAsync();post=(await store.ListAsync(actor,new RecordQuery("board"))).Single();Check(post.Fields["attachmentIds"].Length>0,"Attachment not bound");var reply=Tree(board).OfType<ToolStrip>().SelectMany(t=>Commands(t.Items)).Single(b=>b.Text=="답글·댓글 작성");reply.PerformClick();board.SetField("content","합성 댓글");await board.SaveAsync();Check((await store.ListAsync(actor,new RecordQuery("board"))).Single(r=>r.Id!=post.Id).Fields["parentId"]==post.Id,"Reply not bound to original post");await store.SaveUserAsync(actor,null,"Other project reader","viewer",[q.Id],false,"other-reader-test66");var other=await store.LoginAsync("Other project reader","other-reader-test66");await Throws(()=>store.GetAsync(other,post.Fields["attachmentIds"]),"FORBIDDEN");});
 await Test("attachment limits and deleted parent fail before record mutation",async()=>{try{await board.AttachLocalFilesAsync(Enumerable.Repeat(original,11));throw new Exception("Attachment count accepted");}catch(InvalidOperationException){}await store.DeleteAsync(actor,"board",post!.Id,post.Revision,true);await Throws(()=>store.SaveAsync(actor,new(null,"board",null,0,new(){{"title","Rejected reply"},{"content","synthetic"},{"parentId",post.Id}})),"PARENT_SCOPE");});
 await Test("new-copy export/import remaps folders, assets and attachment IDs with rollback",async()=>{var bundle=Path.Combine(output,"export.zip");await store.ExportAsync(actor,bundle);var preview=await store.PreviewImportAsync(actor,bundle);await store.ImportAsync(actor,preview,true);var projects=await store.ListAsync(actor,new RecordQuery("projects"));var copy=projects.Single(r=>r.Id!=p.Id&&r.Fields["title"]==p.Fields["title"]);var copied=(await store.ListAsync(actor,new RecordQuery("files",copy.Id))).Single();Check(copied.Fields["folderId"]!=child!.Id&&copied.Fields["assetId"]!=file!.Fields["assetId"],"Copy retained old link IDs");Check((await store.ListAsync(actor,new RecordQuery("file-folders",copy.Id))).Any(r=>r.Id==copied.Fields["folderId"]),"Copied folder missing");await store.RollbackLastImportAsync(actor,true);Check((await store.ListAsync(actor,new RecordQuery("projects"))).Count==2,"Rollback changed original projects");});
 await Test("folder rename/empty trash are revision-bound and confirmed",async()=>{var empty=await files.CreateFolderAsync("빈 폴더");var renamed=await files.RenameFolderAsync(empty.Id,"이름 수정");Check(renamed.Revision==empty.Revision+1&&renamed.Fields["title"]=="이름 수정","Folder rename not persisted");await Throws(()=>store.DeleteAsync(actor,"file-folders",renamed.Id,renamed.Revision,false),"CONFIRMATION");await store.DeleteAsync(actor,"file-folders",renamed.Id,renamed.Revision,true);Check(!(await store.ListAsync(actor,new RecordQuery("file-folders",p.Id))).Any(r=>r.Id==renamed.Id),"Trashed folder remained active");});
 await Test("generated file hash and byte size cannot be relabeled",async()=>{var row=(await store.ListAsync(actor,new RecordQuery("files",p.Id))).Single();var fields=new Dictionary<string,string>(row.Fields){["sha256"]=new string('0',64)};await Throws(()=>store.SaveAsync(actor,new(row.Id,row.Kind,row.ProjectId,row.Revision,fields)),"ASSET_BINDING");fields=new(row.Fields){["size"]="999999"};await Throws(()=>store.SaveAsync(actor,new(row.Id,row.Kind,row.ProjectId,row.Revision,fields)),"ASSET_BINDING");Check((await store.ListAsync(actor,new RecordQuery("files",p.Id))).Single().Revision==row.Revision,"Rejected hash metadata changed the row");});
 }catch(Exception e){fail++;checks.Add(new{name="setup",error=e.ToString()});}finally{File.WriteAllText(Path.Combine(output,"RESULT.json"),JsonSerializer.Serialize(new{pass,fail,syntheticOnly=true,checks,reportReady=false,supervisorAccepted=false},new JsonSerializerOptions{WriteIndented=true}));form.Close();}};Application.Run(form);Console.WriteLine($"RESULT localModulesPass={pass} fail={fail}");return fail==0?0:1;}
 sealed class Services(Identity actor,LocalWorkspace store):IWorkspaceServices {public Identity Actor=>actor;public IWorkspaceData Data=>store;public IIdentityService Identities=>store;public IAssetService Assets=>store;public ILayoutStore Layout=>store;public IReportService Reports{get;}=new UnusedReport();public string DataRoot=>store.DataRoot;}
